			para_suv02 = 2;
		else
			para_suv02 = 3;
		next;
		mes "[Michael]";
		mes "Check your supplies again and look after it.";
	}
	else {
		if (para_suv01 == 22)
			para_suv02 = 2;
		else
			para_suv02 = 3;
		mes "A "+ getarg(.@i+2) +", Uniform and Boots all 3 supplies.";
		mes "Please check it again.";
		next;
		mes "[Michael]";
		mes "I hope they're useful to you.";
		mes getarg(.@i+4);
	}
	close;
